       $links$[{"href":"/texas-news","kind":"hub","label":"Texas News"},{"href":"/news/2026-08-09-reeves-county-2gw-data-center-campus","kind":"article","label":"Reeves County data center campus"},{"href":"/news/2026-08-08-amazon-pecos-ai-data-center-emissions","kind":"article","label":"Amazon Pecos AI data center"}]$links$::jsonb internal_links
)
