       $links$[{"href":"/news/2026-08-09-harris-county-ice-shooting-investigation","kind":"article","label":"Harris County ICE shooting investigation"},{"href":"/news/2026-08-09-ice-body-cameras-texas-enforcement","kind":"article","label":"ICE body camera policy"},{"href":"/houston","kind":"hub","label":"Houston"}]$links$::jsonb internal_links
)
